-- Canada: school logos, photos and short descriptions from Wikipedia / Wikimedia Commons (free licences, credit saved).
-- Only fills empty fields. HEC Montreal and UQO left out (Wikipedia matched the wrong page). Safe to re-run.
update schools s set
  logo_url=coalesce(s.logo_url,v.logo), logo_credit=coalesce(s.logo_credit,v.lc),
  image_url=coalesce(s.image_url,v.img), image_credit=coalesce(s.image_credit,v.ic),
  description=coalesce(s.description,v.d), description_credit=coalesce(s.description_credit,v.dc)
from (values
('0d996d07-9006-427e-b299-4b5d115e9110','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Universit%C3%A4t_Montreal_Logo.svg/500px-Universit%C3%A4t_Montreal_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Jean-Claude Lahaye (1923-1999), Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Universit%C3%A9_de_Montr%C3%A9al%2C_Pavillon_Roger-Gaudry.JPG/1280px-Universit%C3%A9_de_Montr%C3%A9al%2C_Pavillon_Roger-Gaudry.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Laurent Bélanger, CC BY-SA 4.0, Wikimedia Commons','The Université de Montréal is a French-language public research university in Montreal, Quebec, Canada. The university''s main campus is located  in the Côte-des-Neiges neighborhood of Côte-des-Neiges–Notre-Dame-de-Grâce on Mount Royal near the Outremont Summit, in the borough of Outremont. The institution comprises thirteen faculties, more than sixty departments and two affiliated schools: Polytechnique Montréal and HEC Montréal.','Description: Wikipedia, CC BY-SA 4.0'),
('6d889f9d-d0a9-401d-9036-d238c041207e','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Logo_York_University.svg/500px-Logo_York_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: SVG erstellt mit Inkscape, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/YorkUComputerScienceAndEngineeringBuilding.jpg/1280px-YorkUComputerScienceAndEngineeringBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Raysonho @ Open Grid Scheduler / Grid Engine, Public domain, Wikimedia Commons','York University is a public research university based in Toronto, Ontario, Canada. It is Canada''s third-largest university, with approximately 53,500 students, 7,000 faculty and staff, and over 375,000 alumni worldwide. It has 11 faculties, including the Lassonde School of Engineering, Schulich School of Business, Osgoode Hall Law School, Glendon College, and 32 research centres.','Description: Wikipedia, CC BY-SA 4.0'),
('1263a1a6-98e8-42a9-8acd-2fd9acd61976','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Carleton_University_Logo.svg/500px-Carleton_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Carleton University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/CarletonUniversity2022.jpg/1280px-CarletonUniversity2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Harleyd613, CC BY-SA 4.0, Wikimedia Commons','Carleton University is an English-language public research university in Ottawa, Ontario, Canada. Founded in 1942 as Carleton College, the institution originally operated as a private, non-denominational evening college to serve returning World War II veterans. Carleton was chartered as a university by the provincial government in 1952 through The Carleton University Act, which was then amended in 1957, giving the institution its current name.','Description: Wikipedia, CC BY-SA 4.0'),
('e6e07660-48f0-420f-97ec-4dd4c8264457','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Universit%C3%A9_laval.jpg/500px-Universit%C3%A9_laval.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Pisenr, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Pavillon_Louis-Jacques-Casault_-_Universit%C3%A9_-Laval_-_Quebec_City_-_October_2007.jpg/1280px-Pavillon_Louis-Jacques-Casault_-_Universit%C3%A9_-Laval_-_Quebec_City_-_October_2007.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Colin Rose from Montreal, Canada, CC BY-SA 2.0, Wikimedia Commons','Université Laval is a public research university in Quebec City, Quebec, Canada. Université Laval traces its roots to the Séminaire de Québec, which was founded by François de Montmorency-Laval in 1663. Université Laval is the oldest institution of higher education in Canada, as well as the first North American institution to offer higher education in French.','Description: Wikipedia, CC BY-SA 4.0'),
('e70bc46d-77be-4449-93e1-591f11e04eb0',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Acadia_University_1.jpg/1280px-Acadia_University_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Ryan Stevens, CC BY 2.0, Wikimedia Commons','Acadia University is a public, predominantly undergraduate university located in Wolfville, Nova Scotia, Canada, with some graduate programs at the master''s level and one at the doctoral level. The enabling legislation consists of the Acadia University Act and the Amended Acadia University Act 2000.
The Wolfville Campus houses Acadia University Archives and the Acadia University Art Gallery.','Description: Wikipedia, CC BY-SA 4.0'),
('890bc234-8faf-4dcf-b8c5-da0dc787961a','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/ECUAD-Logo_RGB.svg/500px-ECUAD-Logo_RGB.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Emily Carr University of Art and Design, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Emily_Carr_University_of_Art_and_Design%2C_exterior%2C_Vancouver%2C_BC_%28May_2025%29.jpg/1280px-Emily_Carr_University_of_Art_and_Design%2C_exterior%2C_Vancouver%2C_BC_%28May_2025%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: BriefEdits, CC BY-SA 3.0, Wikimedia Commons','The Emily Carr University of Art and Design is a public university of art and design located in Vancouver, British Columbia, Canada. Founded in 1925 as the Vancouver School of Decorative and Applied Arts, it is the oldest public post-secondary institution in British Columbia dedicated to professional education in the arts, media, and design. The university is named for Canadian artist and writer Emily Carr, who was known for her Modernist and Post-Impressionist artworks.','Description: Wikipedia, CC BY-SA 4.0'),
('94f34f2e-2f9d-4140-bf3e-f723ea13a7b0','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/Mount_Royal_University_Logo.svg/500px-Mount_Royal_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Mount Royal University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Mount-Royal-College-Szmurlo.jpg/1280px-Mount-Royal-College-Szmurlo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: No machine-readable author provided. Cszmurlo assumed (based on copyright claims, CC BY-SA 3.0, Wikimedia Commons','Mount Royal University is a public university in Calgary, Alberta, Canada. Originally “Mount Royal College,” Mount Royal University was granted university status in 2009 by the provincial government. The university has an average class size of 30 students and currently offers 13 degrees and 37 majors, in addition to diplomas, post-bachelor certificates and a variety of credit-free programs.','Description: Wikipedia, CC BY-SA 4.0'),
('4c3f0735-e2c3-4792-8c4f-042e744ce793','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Logo-uqar_2015.svg/500px-Logo-uqar_2015.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Rimouski_-_Entr%C3%A9e_principale.jpg/1280px-Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Rimouski_-_Entr%C3%A9e_principale.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: AzertyFab, CC BY-SA 3.0, Wikimedia Commons','The Université du Québec à Rimouski is a public university located in Rimouski, Quebec, Canada, with a campus in Lévis. Established in 1969, UQAR offers academic training throughout eastern Quebec, including the Chaudière-Appalaches, Gaspésie–Îles-de-la-Madeleine, Haute-Côte-Nord, and Manicouagan areas. The university also has permanent offices in Gaspé and Rivière-du-Loup.','Description: Wikipedia, CC BY-SA 4.0'),
('03b25832-0531-4f09-ab3a-c82deba3bbde','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/UPEI_Wordmark.svg/500px-UPEI_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: University of Prince Edward Island, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/UPEI_%282633716968%29.jpg/1280px-UPEI_%282633716968%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Martin Cathrae from Charlottetown, PE, Canada, CC BY-SA 2.0, Wikimedia Commons','The University of Prince Edward Island is a public university in Charlottetown, Prince Edward Island, Canada, and the only university in the province. Founded in 1969, the enabling legislation is the University Act, R.S.P.E.I 2000.','Description: Wikipedia, CC BY-SA 4.0'),
('972081bf-aef7-4383-b8b9-82365f3aedc3','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Concordia_univ_montreal_textlogo.png/500px-Concordia_univ_montreal_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/JMSB.jpg/1280px-JMSB.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: MTLskyline, Public domain, Wikimedia Commons','Concordia University is a public English-language research university located in Montreal, Quebec, Canada. Founded in 1974 with the merger of Loyola College and Sir George Williams University, Concordia is one of the three universities in Quebec where English is the primary language of instruction. As of the 2024–2025 academic year, there were 48,657 students enrolled in credit and non-credit courses at Concordia, making the university among the largest in Canada by enrollment.','Description: Wikipedia, CC BY-SA 4.0'),
('01dc316a-8a92-4f64-b15a-9b73c7e04d95',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/Convocation_Hall_University_of_Alberta_Edmonton_Alberta_Canada_02.jpg/1280px-Convocation_Hall_University_of_Alberta_Edmonton_Alberta_Canada_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: WinterforceMedia WinterE229, Public domain, Wikimedia Commons','The University of Alberta is a public research university located in Edmonton, Alberta, Canada. It was founded in 1908 by Alexander Cameron Rutherford, the first premier of Alberta, and Henry Marshall Tory, the university''s first president. It was enabled through the Post-secondary Learning Act.','Description: Wikipedia, CC BY-SA 4.0'),
('25decb60-25d8-47e8-8835-9c35ed464d65','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Algoma_University_wordmark.svg/500px-Algoma_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Algoma University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Algoma_University_2.JPG/1280px-Algoma_University_2.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Fungus Guy, CC BY-SA 3.0, Wikimedia Commons','Algoma University, commonly shortened to Algoma U, is a Canadian public university in the province of Ontario, with campuses in Brampton, Sault Ste. Marie, and Timmins. Algoma U offers bachelor''s degrees, master''s degrees and graduate certificate programs in liberal arts, sciences and professional disciplines.','Description: Wikipedia, CC BY-SA 4.0'),
('66916c52-54ff-4d03-b765-f1289349f38a',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Mount_Saint_Vincent_University.jpg/1280px-Mount_Saint_Vincent_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: misterjerk2, Public domain, Wikimedia Commons','Mount Saint Vincent University, often referred to as the Mount, is a public, primarily undergraduate, university located in Halifax, Nova Scotia, Canada, and was established in 1873. Mount Saint Vincent offers undergraduate programs in arts, science, education, and professional studies. The Mount has 13 graduate degrees in Applied Human Nutrition, School Psychology, Child and Youth Study, Education, Family Studies and Gerontology, Public Relations and Women''s Studies.','Description: Wikipedia, CC BY-SA 4.0'),
('43f9c4b4-d402-4679-9eaf-a8c36e64fc21','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/UofRegina_Logo.svg/500px-UofRegina_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: University of Regina, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/University_of_Regina_Continuing_Development_Centre_-_Regina_%2829125895587%29.jpg/1280px-University_of_Regina_Continuing_Development_Centre_-_Regina_%2829125895587%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Haydn Blackey from Cardiff, Wales, CC BY-SA 2.0, Wikimedia Commons','The University of Regina is a public university located in Regina, Saskatchewan, Canada. Founded in 1911 as a private denominational high school of the Methodist Church of Canada, it began an association with the University of Saskatchewan as a junior college in 1925. It disaffiliated from its Methodist founders and fully ceded to the university in 1934; in 1961 it attained degree-granting status as the Regina Campus of the University of Saskatchewan.','Description: Wikipedia, CC BY-SA 4.0'),
('3a2455d2-432a-44d5-a011-522c43a4c630',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/First_Nations_University_2021.jpg/1280px-First_Nations_University_2021.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: daryl_mitchell, CC BY-SA 2.0, Wikimedia Commons','The First Nations University of Canada is a post-secondary institution and federated college of the University of Regina, based in the Canadian province of Saskatchewan. FNUniv operates three campuses within the province, in Prince Albert, Regina, and Saskatoon. The university offers academic programs in business, the humanities, social sciences, and sciences; including a number of programs focused around Indigenous practices.','Description: Wikipedia, CC BY-SA 4.0'),
('94adc91b-a5f8-4c63-b909-a4a918a7517d','https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Dalhousie_University_Wordmark_2014.svg/500px-Dalhousie_University_Wordmark_2014.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Henri_Hicks_Building%2C_Dalhousie_University.jpg/1280px-Henri_Hicks_Building%2C_Dalhousie_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: mricon, CC BY-SA 2.0, Wikimedia Commons','Dalhousie University is a large public research university in Nova Scotia, Canada, with three campuses in Halifax, a fourth in Bible Hill, and two satellite medical school campuses, in Saint John, New Brunswick and in Cape Breton. Dalhousie offers over 200 degree programs in 13 undergraduate, graduate, and professional faculties. The university is a member of the U15, a group of research-intensive universities in Canada.','Description: Wikipedia, CC BY-SA 4.0'),
('058d3791-8d23-4e86-aeb3-c49071ef58c3',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Taylor-Institute-east-exterior-schulich.jpg/1280px-Taylor-Institute-east-exterior-schulich.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Jgcab, CC BY-SA 4.0, Wikimedia Commons','The University of Calgary is a public research university located in Calgary, Alberta, Canada. The University of Calgary started in 1944 as the Calgary branch of the University of Alberta, founded in 1908, prior to being instituted into a separate, autonomous university in 1966. It is composed of 14 faculties and over 85 research institutes and centres.','Description: Wikipedia, CC BY-SA 4.0'),
('14adea28-4bd9-4410-8bcc-96ebce340d43','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/Athabasca_University_Logo.svg/500px-Athabasca_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Athabasca University, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/5/56/AU2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Stephen Addison, CC BY-SA 3.0, Wikimedia Commons','Athabasca University is a Canadian public university that primarily operates through online distance education. Founded in 1970, it is one of four comprehensive academic and research universities in Alberta, and was the first Canadian university to specialize in distance education.','Description: Wikipedia, CC BY-SA 4.0'),
('977a83eb-de2f-4300-a44e-446400aa121d',null,null,null,null,'Nipissing University is a public university located in North Bay, Ontario, Canada. Its scenic hilltop campus overlooks Lake Nipissing. The university has established a strong reputation in fields such as education, arts, science, business, and nursing, and is home to the prestigious Schulich School of Education.','Description: Wikipedia, CC BY-SA 4.0'),
('6f88aa65-32f6-4164-aea2-fa65da5c34a7','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Winnipeg_univ_ca_textlogo.png/500px-Winnipeg_univ_ca_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/UofW.JPG/1280px-UofW.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: KrazyTea, CC BY-SA 3.0, Wikimedia Commons','The University of Winnipeg is a public research university in Winnipeg, Manitoba, Canada. It offers undergraduate programs in art, business, economics, education, science and applied health as well as graduate programs. UWinnipeg''s founding colleges were Manitoba College and Wesley College, which merged to form United College in 1938.','Description: Wikipedia, CC BY-SA 4.0'),
('cc9dd73d-3c07-42ec-a5db-904386ccebb7','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Fraser_valley_univ_logo.svg/500px-Fraser_valley_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons',null,null,'The University of the Fraser Valley, formerly known as University College of the Fraser Valley and Fraser Valley College, is a public university with campuses in Abbotsford, Chilliwack, Mission and Hope, British Columbia, Canada. Founded in 1974 as Fraser Valley College, it was a response to the need for expanded vocational training in the communities of the Fraser Valley.  In 1991, it became a university college, with degree-granting status.','Description: Wikipedia, CC BY-SA 4.0'),
('b6fb2eeb-1cca-4d51-83c5-265e609c32f5','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Mcgill_univ_ca_logo.png/500px-Mcgill_univ_ca_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: patent of arms for James McGill (1744–1813) granted by England''s Garter-King-at-, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Arts_Building%2C_McGill_University%2C_Aug_31_2022.jpg/1280px-Arts_Building%2C_McGill_University%2C_Aug_31_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: D. Benjamin Miller, CC0, Wikimedia Commons','McGill University is an English-language public research university in Montreal, Quebec, Canada. Founded in 1821 by royal charter, the university bears the name of James McGill, a Scottish merchant, whose bequest in 1813 established the University of McGill College. In 1885, the name of the university was officially changed to McGill University.','Description: Wikipedia, CC BY-SA 4.0'),
('ec878c05-ccde-4f52-b45d-64d51c0b2550',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/UniversityOfManitobaAdministrationBuilding.jpg/1280px-UniversityOfManitobaAdministrationBuilding.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','CC BY-SA 3.0, Wikimedia Commons','The University of Manitoba is a public research university in Winnipeg, Manitoba, Canada. Founded in 1877, it is the first university in Western Canada. Both by total student enrolment and campus area, the University of Manitoba is the largest university in the province of Manitoba.','Description: Wikipedia, CC BY-SA 4.0'),
('a1fa6a18-6be6-4ddc-a20f-9d42aa3ba4f7',null,null,null,null,'Bishop''s University is a small English-language liberal arts university in Lennoxville, a borough of Sherbrooke, Quebec, Canada. The founder of the institution was the Anglican Bishop of Quebec, George Mountain, who also served as the first principal of McGill University. It is one of three universities in the province of Quebec that teach primarily in English, with the others being McGill University and Concordia University, both in Montreal.','Description: Wikipedia, CC BY-SA 4.0'),
('db725d76-0aa4-4781-b3bf-c0ee4a1b510b','https://upload.wikimedia.org/wikipedia/commons/f/fc/Logo_INRS_-_Institut_national_de_la_recherche_scientifique.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Logo: Institut national de la recherche scientifique, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Edifice_quebec_INRS.jpg/1280px-Edifice_quebec_INRS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Hélène Simard, CC BY-SA 3.0, Wikimedia Commons','The Institut national de la recherche scientifique is the research-oriented constituent university of the Université du Québec system that offers only graduate studies. INRS conducts research in four broad sectors: water, earth and the environment; energy, materials and telecommunications; human, animal and environmental health; and urbanization, culture and society.
INRS has facilities in Quebec City, Montreal, Laval, and Varennes.','Description: Wikipedia, CC BY-SA 4.0'),
('37fd285e-a0cf-4c17-9ea9-a401b84eea63','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3b/NSCAD_Logo.svg/500px-NSCAD_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: NSCAD University, Public domain, Wikimedia Commons',null,null,'NSCAD University, also known as the Nova Scotia College of Art and Design, is a public art university in Halifax, Nova Scotia, Canada. The university is a co-educational institution that offers bachelor''s and master''s degrees. The university also provides continuing education services through its School of Extended Studies.','Description: Wikipedia, CC BY-SA 4.0'),
('2cdbde41-b2bf-4824-baa6-325c17a2f374',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Thompson_River_University_3.jpg/1280px-Thompson_River_University_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Kiyoteru Awaji, CC BY-SA 4.0, Wikimedia Commons','Thompson Rivers University is a public research university in Kamloops, British Columbia, Canada. The university''s name comes from the two rivers that converge in Kamloops, the North Thompson and South Thompson. TRU is one of six research universities in B.C. It is the province''s only dual-sector research university—meaning it offers both academic and applied education—and offers a dual-sector education.','Description: Wikipedia, CC BY-SA 4.0'),
('684f3c84-e5ea-4354-aa6f-88ff6a4fb907','https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Univ_of_victoria_logo.png/500px-Univ_of_victoria_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/UVic_Clearihue_Building.jpg/1280px-UVic_Clearihue_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Tloren5, CC BY-SA 4.0, Wikimedia Commons','The University of Victoria is a public research university located in the municipalities of Oak Bay and Saanich, British Columbia, Canada. 
It is a mid-to-large Canadian research university with strong environmental science, law, and Indigenous studies strengths, located in a coastal, nature-rich campus setting that emphasizes applied learning and sustainability.
Established in 1903 as Victoria College, the institution was initially an affiliated college of McGill University until 1915.','Description: Wikipedia, CC BY-SA 4.0'),
('02422147-3142-4dd4-82e0-05ef9cd049bb',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/McMaster_University_campus.jpg/1280px-McMaster_University_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Jokehoe, CC BY-SA 4.0, Wikimedia Commons','McMaster University is a public research university in Hamilton, Ontario, Canada. The main McMaster campus is on 152.4 hectares of land near the residential neighbourhoods of Ainslie Wood and Westdale, adjacent to the Royal Botanical Gardens. It operates six academic faculties: the DeGroote School of Business and the faculties of Engineering, Health Sciences, Humanities, Social Science, and Science.','Description: Wikipedia, CC BY-SA 4.0'),
('44b13810-abb8-45f8-a343-d738e56c03e4','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/Univ_ottawa_red_textlogo.png/500px-Univ_ottawa_red_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/UOttawa-Tabaret_Hall-2008-05-05.jpg/1280px-UOttawa-Tabaret_Hall-2008-05-05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: RobCA, Public domain, Wikimedia Commons','The University of Ottawa, often referred to as uOttawa, is a bilingual public research university in Ottawa, Ontario, the capital city of Canada. The main campus is located on 42.5 hectares directly to the northeast of Downtown Ottawa across the Rideau Canal in the Sandy Hill neighbourhood.
The University of Ottawa was first established as the College of Bytown in 1848 by the first bishop of the Catholic Archdiocese of Ottawa, Joseph-Bruno Guigues.','Description: Wikipedia, CC BY-SA 4.0'),
('b5b26aa9-7174-4289-a4b3-02ce977d868d','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/Brandon_univ_textlogo.png/500px-Brandon_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/U_of_Brandon_-_Clark_Hall.jpg/1280px-U_of_Brandon_-_Clark_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Krazytea, CC BY-SA 4.0, Wikimedia Commons','Brandon University is a university located in the city of Brandon, Manitoba, Canada, with an enrolment of approximately 3,375 full-time and part-time undergraduate and graduate students.  The current location was founded on July 13, 1899, as Brandon College as a Baptist institution.  It was chartered as a university by then President John E. Robbins on June 5, 1967.','Description: Wikipedia, CC BY-SA 4.0'),
('bc5ef839-6d38-44be-be78-2f4e3ee46a60','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Kwantlen_Polytechnic_University_Logo.svg/500px-Kwantlen_Polytechnic_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Kwantlen Polytechnic University, Public domain, Wikimedia Commons',null,null,'Kwantlen Polytechnic University is a public undergraduate degree-granting polytechnic university in British Columbia, Canada, with campuses in Surrey, Richmond, Cloverdale, Whalley, and Langley. KPU is one of the largest institutions by enrolment in British Columbia garnering a total of 20,000 students and 1,400 faculty members across its five locations, encompassing the Metro Vancouver district. KPU provides undergraduate and vocational education including bachelor''s degrees, associate degrees, diplomas, certificates, apprenticeships, and citations in more than 140 diverse programs.','Description: Wikipedia, CC BY-SA 4.0'),
('a0208ac5-9d8e-4e3b-89f2-2b535aed71ca','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/OCAD_University_Logo.png/500px-OCAD_University_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Bruce Mau Design, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/7/74/OCADNight1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: John Vetterli from Toronto, Canada, CC BY-SA 2.0, Wikimedia Commons','The Ontario College of Art and Design University, branded as OCAD University or OCAD U, is a public art university in Toronto, Ontario, Canada. Its main campus is located within Toronto''s Grange Park and Entertainment District neighbourhoods.
The university is co-educational and operates three academic faculties – the Faculty of Art, the Faculty of Arts and Science, and the Faculty of Design – which offer programs at the undergraduate and graduate levels, as well as certificate programs and continuing education courses.','Description: Wikipedia, CC BY-SA 4.0'),
('88bcb3aa-6b5c-442b-8f0e-d800ff050d32',null,null,null,null,'Trent University is a public university in Peterborough, Ontario, with a satellite campus in Oshawa, which serves the Regional Municipality of Durham. Founded in 1964, the university is known for its Oxbridge college system and 11 on-campus nature reserves. The university''s main Symons campus is located on the Otonabee River at the northeast corner of the City of Peterborough.','Description: Wikipedia, CC BY-SA 4.0'),
('3eb529d0-4129-453f-8ec4-29ca24578bbd','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Universit%C3%A9_Sainte-Anne_Logo.svg/500px-Universit%C3%A9_Sainte-Anne_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Université Sainte-Anne, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/SteAnnes.jpg/1280px-SteAnnes.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Verne Equinox at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons','Université Sainte-Anne is a French-language university in Pointe-de-l''Église, Nova Scotia, Canada. It and the Université de Moncton in New Brunswick are the only French-language universities in the Maritime Provinces.','Description: Wikipedia, CC BY-SA 4.0'),
('f22c4c6d-2d8f-44e9-806e-ae9acbe47ce7','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Windsor_univ_ca_textlogo.png/500px-Windsor_univ_ca_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/University_of_Windsor_Alumni_Hall.jpg/1280px-University_of_Windsor_Alumni_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Krylan22, CC BY-SA 4.0, Wikimedia Commons','The University of Windsor is a public research university in Windsor, Ontario, Canada. It is Canada''s southernmost university. It has approximately 17,500 students.','Description: Wikipedia, CC BY-SA 4.0'),
('dc76ebd7-662f-444c-b60b-2b64ee8349d0','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/QueensU_Wordmark.svg/500px-QueensU_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Connormah, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Queen%27sDouglas.JPG/1280px-Queen%27sDouglas.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: No machine-readable author provided. GreenCommons assumed (based on copyright cl, Public domain, Wikimedia Commons','Queen''s University at Kingston, commonly known as Queen''s University or simply Queen''s, is a public research university in Kingston, Ontario, Canada. Queen''s holds more than 1,400 hectares of land throughout Ontario and owns Herstmonceux Castle in East Sussex, England. Queen''s is organized into eight faculties and schools.','Description: Wikipedia, CC BY-SA 4.0'),
('7cd9cb27-27e4-431b-ad9a-e03b10823242',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a7/CollegeBuilding-UofS.jpg/1280px-CollegeBuilding-UofS.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: SriMesh, CC BY-SA 3.0, Wikimedia Commons','The University of Saskatchewan is a Canadian public research university, founded on March 19, 1907, and located on the east side of the South Saskatchewan River in Saskatoon, Saskatchewan, Canada.
An "Act to establish and incorporate a University for the Province of Saskatchewan" was passed by the provincial legislature in 1907. It established the provincial university on March 19, 1907 "for the purpose of providing facilities for higher education in all its branches and enabling all persons without regard to race, creed or religion to take the fullest advantage".','Description: Wikipedia, CC BY-SA 4.0'),
('7bf7b280-9003-4b55-a54e-a544ed3b0fc3','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Brock_University_Logo_2022.svg/500px-Brock_University_Logo_2022.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Brock University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/Brock_University_%287990168355%29.jpg/1280px-Brock_University_%287990168355%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Matt Clare from Burlington, Canada, CC BY-SA 2.0, Wikimedia Commons','Brock University is a public research university in St. Catharines, Ontario, Canada. It is the only university in Canada in a UNESCO Biosphere Reserve, at the centre of Canada''s Niagara Peninsula on the Niagara Escarpment.','Description: Wikipedia, CC BY-SA 4.0'),
('a61a464c-6cb5-49e5-997b-1d7018f41641','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Lakehead_univ_textlogo.png/500px-Lakehead_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/0/07/Lakehead_University_Summer_Campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Office of Communications, Lakehead University, CC BY 2.5, Wikimedia Commons','Lakehead University is a public research university with campuses in Thunder Bay and Orillia, Ontario, Canada. Lakehead University, shortened to ''Lakehead U'', is non-denominational and provincially supported. It has undergraduate programs, graduate programs, the Bora Laskin Faculty of Law, the only internationally accredited business school in northern Ontario, and is home to the western campus of the Northern Ontario School of Medicine.','Description: Wikipedia, CC BY-SA 4.0'),
('f6203b95-163f-4a3c-814f-0dea05945d49','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/OntarioTech_primary_2019.svg/500px-OntarioTech_primary_2019.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Ontario Tech University, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/d/de/General_Motors_of_Canada_Automotive_Centre_of_Excellence.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Thehype2049, CC BY-SA 3.0, Wikimedia Commons','The University of Ontario Institute of Technology, branded as Ontario Tech University or Ontario Tech, is a public research university located in Oshawa, Ontario, Canada. The university''s main campus is located on approximately 160 hectares of land in northern Oshawa, while its secondary satellite campus is situated in downtown Oshawa. The university is a co-educational institution that operates seven academic faculties.','Description: Wikipedia, CC BY-SA 4.0'),
('6e513a92-f6f4-4b57-8d66-36dd5be5be0f','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Moncton_universite_logo.svg/500px-Moncton_universite_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/5/52/Universit%C3%A9_de_Moncton_Campus_de_Shippagan_1.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Claude Boucher, CC BY-SA 3.0, Wikimedia Commons','The Université de Moncton is a Canadian French-language university in New Brunswick. It includes campuses in Edmundston, Moncton, and Shippagan.
The university was founded in 1963 following the recommendations of the royal commission on higher education in New Brunswick.','Description: Wikipedia, CC BY-SA 4.0'),
('673178d4-a435-458e-85a1-05f5f6b0080f','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/TELUQ_rvb_500x174.png/500px-TELUQ_rvb_500x174.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Dominique Fourcaudot (COMM-TÉLUQ), Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/T%C3%89LUQ_panorama.jpg/1280px-T%C3%89LUQ_panorama.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Dominique Fourcaudot (COMM-TÉLUQ), CC BY-SA 4.0, Wikimedia Commons','Université TÉLUQ is a public French-language distance learning university, part of the Université du Québec system. Originally founded in 1972 as the Telé-université, Université du Québec commission to develop distance education courses, Université TÉLUQ is now a full university which offers programs in undergraduate and graduate studies. It is the only French-language university education institution in North America to offer all of its courses and programs at all three university cycles remotely and continuously.','Description: Wikipedia, CC BY-SA 4.0'),
('3f7a27fb-5ed2-42f7-b5bc-33f873ea637d','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Coat_of_Arms_of_Vancouver_Island_University.png/500px-Coat_of_Arms_of_Vancouver_Island_University.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: SheLikesHeraldry, CC BY 4.0, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Vancouver_Island_University_Faculty_of_Management.jpg/1280px-Vancouver_Island_University_Faculty_of_Management.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Nle1229, CC BY-SA 3.0, Wikimedia Commons','Vancouver Island University is a Canadian public research university serving Vancouver Island and coastal British Columbia. Malaspina College opened in 1969. The main campus is located in Nanaimo, with regional campuses in Duncan and Powell River.','Description: Wikipedia, CC BY-SA 4.0'),
('ebe01186-bdc6-419d-a8d2-413ed97e168d','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/SFU-block-logo.svg/500px-SFU-block-logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Originally uploaded by Mwtoews, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Academic_quad_at_sfu.jpg/1280px-Academic_quad_at_sfu.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: kirsten, CC BY-SA 2.0, Wikimedia Commons','Simon Fraser University is a public research university in British Columbia, Canada. It maintains three campuses in Greater Vancouver, respectively located in Burnaby, Surrey, and Downtown Vancouver. The 170-hectare main Burnaby campus on Burnaby Mountain, located 15 kilometres from downtown Vancouver, was established in 1965 and comprises more than 37,000 students and 200,000 alumni.','Description: Wikipedia, CC BY-SA 4.0'),
('f6fa150f-e620-4559-b69e-5d50cae8aebb',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Facing_North.jpg/1280px-Facing_North.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: KTMAR, CC BY 3.0, Wikimedia Commons','The University of Toronto is a public research university with three main campuses in the Greater Toronto Area of Ontario, Canada. Based on the grounds that surround Queen''s Park in Toronto, it was founded by royal charter in 1827 as King''s College, the first institution of higher learning in Upper Canada. Originally controlled by the Church of England, the university assumed its present name in 1850 upon becoming a secular institution.','Description: Wikipedia, CC BY-SA 4.0'),
('325fa582-624c-4e07-8f75-0a3a94be267b','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/CapeBretonUniversityLogo.svg/500px-CapeBretonUniversityLogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Cape Breton University  The original uploader was MPen92 at English Wikipedia., Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Shannon_School_of_Business.JPG/1280px-Shannon_School_of_Business.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: MPen92, CC BY-SA 4.0, Wikimedia Commons','Cape Breton University is a public university located in Sydney, Nova Scotia, Canada. It is the only post-secondary degree-granting institution within the Cape Breton Regional Municipality and on Cape Breton Island. 
The university is enabled by the Cape Breton University Act passed by the Nova Scotia House of Assembly.','Description: Wikipedia, CC BY-SA 4.0'),
('c0dae375-b222-4ebe-a687-3a290bdef5ad','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Laurentian_univ_textlogo.svg/500px-Laurentian_univ_textlogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Sudbury_fullsizeoutput_31fc_%2830570602508%29.jpg/1280px-Sudbury_fullsizeoutput_31fc_%2830570602508%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: JasonParis from Toronto, Canada, CC BY 2.0, Wikimedia Commons','Laurentian University, officially Laurentian University of Sudbury, is a mid-sized bilingual public university in Greater Sudbury, Ontario, Canada, incorporated on March 28, 1960. Laurentian offers a variety of undergraduate, graduate-level, and doctorate degrees. Laurentian is the largest bilingual provider of distance education in Canada.','Description: Wikipedia, CC BY-SA 4.0'),
('843e636b-f7a0-4029-9485-5b18e245469e','https://upload.wikimedia.org/wikipedia/commons/c/c9/Poly.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Logo: Polytechnique Montréal, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/%C3%89cole_Polytechnique_de_Montr%C3%A9al.jpg/1280px-%C3%89cole_Polytechnique_de_Montr%C3%A9al.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Chicoutimi, CC BY-SA 3.0, Wikimedia Commons','Polytechnique Montréal is a public research university affiliated with the Université de Montréal in Montreal, Quebec, Canada. The school offers graduate and postgraduate training, and is active in research. Following tradition, new Bachelors of Engineering graduating from Polytechnique Montréal receive an Iron Ring, during the Canadian Ritual of the Calling of an Engineer ceremony.','Description: Wikipedia, CC BY-SA 4.0'),
('11348a9e-21f4-4637-904a-7958fd445599',null,null,null,null,'The Université de Saint-Boniface is a French-language public university located in the St. Boniface neighbourhood of Winnipeg, Manitoba, Canada. An affiliated institution of the University of Manitoba, the university offers general and specialized university degree programs as well as technical and professional training.','Description: Wikipedia, CC BY-SA 4.0'),
('df8e11c2-7f3a-43e2-b8ca-cf3e44a74c1b','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/University_of_Guelph_logo.svg/500px-University_of_Guelph_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: University of Guelph, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Johnston_Green%2C_University_of_Guelph_-_Guelph%2C_ON_%282026%29-001.jpg/1280px-Johnston_Green%2C_University_of_Guelph_-_Guelph%2C_ON_%282026%29-001.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: JFVoll, CC BY-SA 3.0, Wikimedia Commons','The University of Guelph is a comprehensive public research university in Guelph, Ontario, Canada. It was established in 1964 after the amalgamation of Ontario Agricultural College, the MacDonald Institute, and the Ontario Veterinary College, and has since grown to an institution of over 30,000 students from more than 140 countries and employs 823 full-time faculty as of 2025. It offers 94 undergraduate degrees, 48 graduate programs, and 6 associate degrees in many different disciplines.','Description: Wikipedia, CC BY-SA 4.0'),
('663200da-f3f7-4c42-bf27-e2ace87fe988','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Laurier_univ_textlogo.png/500px-Laurier_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Schlegel_Centre_%28Laurier%27s_school_of_business_and_economics%29.JPG/1280px-Schlegel_Centre_%28Laurier%27s_school_of_business_and_economics%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: LeonV, CC BY-SA 4.0, Wikimedia Commons','Wilfrid Laurier University is a Public university in Ontario, Canada, with campuses in Waterloo, Brantford and Milton. It is named in honour of Sir Wilfrid Laurier, the seventh prime minister of Canada. Laurier offers undergraduate and graduate programs in a variety of fields with over 17,000 full-time undergraduate students, over 1,000 full-time graduate students, and nearly 4,000 part-time students as of late 2019.','Description: Wikipedia, CC BY-SA 4.0'),
('09d436f1-10b1-44dc-aeb2-8864ad3f8cf8','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/British_columbia_ca_univ_logo.svg/500px-British_columbia_ca_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Irving_K._Barber_Library.jpg/1280px-Irving_K._Barber_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: CjayD, CC BY 2.0, Wikimedia Commons','The University of British Columbia is a public research university with two main campuses near Vancouver and Kelowna, in British Columbia, Canada. With an annual research budget of $893 million, UBC funds 9,992 projects annually in various fields of study within the industrial sector, as well as governmental and non-governmental organizations.
The Vancouver campus is situated on Point Grey campus lands, an unincorporated area bordering the University Endowment Lands in proximity to the City of Vancouver.','Description: Wikipedia, CC BY-SA 4.0'),
('4648d072-a5b2-4f43-90a4-59b46c255646','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/Uwaterloo_wordmark.svg/500px-Uwaterloo_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: University of Waterloo, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/University_of_Waterloo_%28Waterloo_Campus%29_-_Waterloo%2C_Ontario.jpg/1280px-University_of_Waterloo_%28Waterloo_Campus%29_-_Waterloo%2C_Ontario.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: JFVoll, CC BY-SA 4.0, Wikimedia Commons','The University of Waterloo is a public research university located in Waterloo, Ontario, Canada. The main campus is on 404 hectares of land adjacent to uptown Waterloo and Waterloo Park. The university also operates three satellite campuses and four affiliated university colleges.','Description: Wikipedia, CC BY-SA 4.0'),
('f9ea13d7-066f-4a6b-a2d8-dca321f7487d','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/CapU_logo_horizontal_rgb.png/500px-CapU_logo_horizontal_rgb.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Capilano University, CC BY-SA 4.0, Wikimedia Commons',null,null,'Capilano University is a teaching-focused public university based in North Vancouver, British Columbia, Canada, located on the slopes of the North Shore Mountains, with programming that also serves the Sea-to-Sky Corridor and the Sunshine Coast. The university is named after Chief Joe Capilano, leader of the Squamish people from 1895 to 1910.
Capilano University''s degree programs are approved by the Government of British Columbia''s Ministry of Advanced Education, Skills and Training.','Description: Wikipedia, CC BY-SA 4.0'),
('5928c28e-2d61-409e-9cd0-8a903a57432c','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/MacEwanU-Logo.svg/500px-MacEwanU-Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: MacEwanMedia, Vectorization:  Jeromi Mikhael, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/0/0e/MacEwan_University_Edmonton_%288726219457%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Kevin M Klerks from Inverhuron, Canada, CC BY 2.0, Wikimedia Commons','Grant MacEwan University, commonly known as MacEwan University, is a public university located in downtown Edmonton, Alberta, Canada. Originally established as a community college which was named in honour of Dr. Grant MacEwan, 9th Lieutenant Governor of Alberta in 1971, Grant MacEwan College officially transitioned into a university in 2009 under the Post-Secondary Learning Act.','Description: Wikipedia, CC BY-SA 4.0'),
('a9e92987-4bc9-4cc7-a5e9-6d126d3e6b02','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/Rmc_canada_textlogo.png/500px-Rmc_canada_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/RMC_Mackenzie_building.JPG/1280px-RMC_Mackenzie_building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: User S23678 on en.wikipedia, Public domain, Wikimedia Commons','The Royal Military College of Canada, abbreviated in English as RMC and in French as CMR, is a military academy and, since 1959, a degree-granting university of the Canadian Armed Forces. It was established in 1874 and conducted its first classes on June 1, 1876. Programs are offered at the undergraduate and graduate levels, both on campus as well as through the college''s distance learning program via the Division of Continuing Studies.','Description: Wikipedia, CC BY-SA 4.0'),
('15fbcbf2-bf3f-4eea-9c88-c2e7e15bd68a','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Universit%C3%A9_de_Sherbrooke_%28logo%29_%282%29.svg/500px-Universit%C3%A9_de_Sherbrooke_%28logo%29_%282%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Université de Sherbrooke, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/Universit%C3%A9_de_Sherbrooke_-_Centre_multifonctionnel.jpg/1280px-Universit%C3%A9_de_Sherbrooke_-_Centre_multifonctionnel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: UncivilFire, CC BY-SA 3.0, Wikimedia Commons','The Université de Sherbrooke is a French-language public research university in Sherbrooke, Quebec, Canada, with a second campus in Longueuil, a suburb on the South Shore of Montreal. It is one of two universities in the Estrie region of Quebec, and the only French-language university for the region.
As of 2022, the Université de Sherbrooke is home to 31,000 students, and an additional 3,000 older learners in continuing education in its "University of the Third Age".','Description: Wikipedia, CC BY-SA 4.0'),
('524f5f1c-ee49-471e-ad25-8c4cff67313e','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Lethbridge_univ_textlogo.png/500px-Lethbridge_univ_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/d/d4/University_of_lethbridge_SU.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Keegan Mullin, Public domain, Wikimedia Commons','The University of Lethbridge is a public comprehensive and research university located in Lethbridge, Alberta, Canada, with a second campus in Calgary, Alberta, and until 2015 a third campus in Edmonton, Alberta.
Founded in the liberal arts tradition, the university offers over 150 undergraduate degree programs in the Arts, Sciences, Management, Education, Health Sciences and Fine Arts. Further, the university has over 50 Masters and PhD programs.','Description: Wikipedia, CC BY-SA 4.0'),
('56e317bc-8ad5-4be1-a748-3614e352c65a','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Yukon_University_logo.png/500px-Yukon_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Yukon University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Panorama_for_the_Yukon_College_Roof.jpg/1280px-Panorama_for_the_Yukon_College_Roof.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: grampymoose, CC BY-SA 2.0, Wikimedia Commons','Yukon University is a public university in the Canadian territory of Yukon. The university''s main campus is based in Whitehorse, although the institution also operates 12 campuses throughout the territory. The university confers bachelor''s degrees, diplomas, certificates as well as trades and vocational training and adult basic education.','Description: Wikipedia, CC BY-SA 4.0'),
('d421e3c2-fb47-4406-b709-45b387aa3328','https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/TMU_logo.svg/500px-TMU_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Toronto Metropolitan University, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/Toronto_Met_Student_Learning_Centre_at_night_2022.jpg/1280px-Toronto_Met_Student_Learning_Centre_at_night_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Canmenwalker, CC BY 4.0, Wikimedia Commons','Toronto Metropolitan University, formerly known as Ryerson University, is a public research university located in Toronto, Ontario, Canada.
The university''s core campus is situated within the Garden District in downtown Toronto, although it also operates facilities elsewhere in the city and a satellite campus in Brampton for its medical school. The university includes nine academic divisions: the Faculty of Arts, the Faculty of Community Services, the Faculty of Engineering and Architectural Science, the Faculty of Science, The Creative School, the Lincoln Alexander School of Law, the Ted Rogers School of Management, the School of Medicine, and the Yeates School of Graduate and Postdoctoral Studies.','Description: Wikipedia, CC BY-SA 4.0'),
('3306b401-6559-4bf0-a40e-9c61f976c9bd','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Western_ontario_univ_textlogo.svg/500px-Western_ontario_univ_textlogo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/University_College%2C_Western_University.jpg/1280px-University_College%2C_Western_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: R.schneider101, CC BY-SA 4.0, Wikimedia Commons','The University of Western Ontario is a public research university in London, Ontario, Canada. The main campus is located on 455 hectares of land, surrounded by residential neighbourhoods and the Thames River bisecting the campus''s eastern portion. The university operates twelve academic faculties and schools.','Description: Wikipedia, CC BY-SA 4.0'),
('2589b475-101d-4c24-a502-dcdfdf0c1810','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Ets_quebec_logo.png/500px-Ets_quebec_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Ecole_de_technologie_superieure_05.jpg/1280px-Ecole_de_technologie_superieure_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Jeangagnon, CC BY-SA 3.0, Wikimedia Commons','École de technologie supérieure, founded in 1974, is a public research university in Montreal, Quebec, Canada and affiliated to the Université du Québec system. The school specializes in applied teaching and research in engineering as well as transferring advanced technologies to companies.
In any given year, 25% of all engineers receiving a diploma from an engineering school or faculty in the province of Quebec graduate from the ÉTS. The school ranks second in Canada for the number of bachelor''s degrees in engineering awarded at the undergraduate level.','Description: Wikipedia, CC BY-SA 4.0'),
('e8930518-f9f3-4a63-a77d-230467e237f9','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Memorial_University_of_Newfoundland_Logo.svg/500px-Memorial_University_of_Newfoundland_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/MemorialUniversity.jpg/1280px-MemorialUniversity.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: User:Neelix, Public domain, Wikimedia Commons','Memorial University of Newfoundland, or MUN, is a public research university in the province of Newfoundland and Labrador, based in St. John''s, with satellite campuses in Corner Brook, Happy Valley-Goose Bay, and Harlow, England.  Memorial University offers certificate, diploma, undergraduate, graduate, and post-graduate programs, as well as online courses and degrees.','Description: Wikipedia, CC BY-SA 4.0'),
('a01a23d1-90ee-49d2-b812-07a537408e97',null,null,'https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Royal_Roads_University.jpg/1280px-Royal_Roads_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Worldneedpeace, CC BY 3.0, Wikimedia Commons','Royal Roads University is a public university with its main campus in Colwood, British Columbia, Canada. The university is located at Hatley Park National Historic Site on Vancouver Island and is the successor to the Royal Roads Military College, which was originally a training base for naval officers and later Canadian Air Force and Army personnel. After the end of the Cold War, the college was decommissioned, however, it was reinstituted following negotiations between the Department of National Defence and the Government of British Columbia by which the Royal Roads University Act was passed, leading to the establishment of Royal Roads University in June 1995.','Description: Wikipedia, CC BY-SA 4.0'),
('94df807f-9cdd-44df-9b7e-8db7da679fb2',null,null,'https://upload.wikimedia.org/wikipedia/commons/f/f8/CampusUQAC07_282.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: service des communications de l''UQAC, CC BY-SA 3.0, Wikimedia Commons','The Université du Québec à Chicoutimi, is a branch of the Université du Québec network founded in 1969 and based in the Chicoutimi borough of Saguenay, Quebec, Canada. UQAC has secondary study centres in La Malbaie, Saint-Félicien, Alma, and Sept-Îles. In 2017, 7500 students were registered and 209 professors worked for the university, making it the fourth largest of the ten Université du Québec branches, after Université du Québec à Montréal, Université du Québec à Trois-Rivières, and École de technologie supérieure.','Description: Wikipedia, CC BY-SA 4.0'),
('72cb9981-e655-4ffc-969c-0c0f43fa3d0e','https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/New_brunswick_univ_logo.svg/500px-New_brunswick_univ_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d4/UNB_OldArtsBuilding.JPG/1280px-UNB_OldArtsBuilding.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Blazingluke at English Wikipedia, CC BY-SA 3.0, Wikimedia Commons','The University of New Brunswick is a public research university with two primary campuses in Fredericton and Saint John, New Brunswick. It is the oldest English-language university in Canada. With Canada''s oldest engineering programme, UNB is consistently ranked by the Times Higher Education amongst the top 300 engineering schools in the world, or top 3% of over 7,000 universities that offer engineering worldwide.','Description: Wikipedia, CC BY-SA 4.0'),
('8e598699-906c-4cde-8879-c27e86901921','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Mount_allison_univ_ca_logo.svg/500px-Mount_allison_univ_ca_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown, Public domain, Wikimedia Commons','https://upload.wikimedia.org/wikipedia/commons/1/1a/Purdy_Crawford_Centre_for_the_Arts.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled','Photo: Jmdc-chicago, CC BY-SA 4.0, Wikimedia Commons','Mount Allison University, founded in 1839, is a public primarily undergraduate liberal arts university located in Sackville, New Brunswick, Canada.
Mount Allison was the first university in the British Empire to award a baccalaureate to a woman. It was also the first university in Canada to grant a bachelor of arts to a woman.','Description: Wikipedia, CC BY-SA 4.0'),
('4d3c356c-5dac-46ed-a0db-6e4259671937','https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/St_mary_univ_halifax_textlogo.png/500px-St_mary_univ_halifax_textlogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Unknown authorUnknown author, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Saint_Marys_HFX.jpg/1280px-Saint_Marys_HFX.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Robert Alfers, Public domain, Wikimedia Commons','Saint Mary''s University is a public university located in Halifax, Nova Scotia, Canada. The school is best known for having nationally leading programs in business and chemistry. The campus is situated in Halifax''s South End and covers approximately 32 hectares.','Description: Wikipedia, CC BY-SA 4.0'),
('c3742177-137c-4914-b402-649dfb30de01','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Montr%C3%A9al_Logo.svg/500px-Universit%C3%A9_du_Qu%C3%A9bec_%C3%A0_Montr%C3%A9al_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: Université du Québec à Montréal, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Pavillon_Judith-Jasmin_UQAM_2.jpg/1280px-Pavillon_Judith-Jasmin_UQAM_2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Great11, CC BY-SA 4.0, Wikimedia Commons','The Université du Québec à Montréal is a French-language public research university based in Montreal, Quebec, Canada. It is the largest constituent element of the Université du Québec system.
UQAM was founded on April 9, 1969, by the government of Quebec, through the merger of the École des beaux-arts de Montréal, a fine arts school; the Collège Sainte-Marie, a classical college; and a number of smaller schools.','Description: Wikipedia, CC BY-SA 4.0'),
('15494535-de6a-44b3-8dcf-0b37ef2d8ce4','https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/UNBC_Logo.svg/500px-UNBC_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Logo: University of Northern British Columbia, Public domain, Wikimedia Commons','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/UNBC.jpg/1280px-UNBC.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail','Photo: Thegrammarguy, CC BY-SA 4.0, Wikimedia Commons','The University of Northern British Columbia is a university serving the northern region of the Canadian province of British Columbia. The main campus is located in Prince George, with additional campuses located in Prince Rupert, Terrace, Quesnel, and Fort St. John.','Description: Wikipedia, CC BY-SA 4.0')
) as v(id,logo,lc,img,ic,d,dc)
where s.id=v.id::uuid and s.country='Canada';
